export function localizeAuthorName(enAuthor: string, lang: LanguageCode): string {
  if (lang === 'en') return enAuthor;
  return AUTHOR_TRANSLATIONS_8LANG[enAuthor]?.[lang] || AUTHOR_TRANSLATIONS_8LANG['Editorial & Historical Research Board'][lang];
}

