        'సా.శ. 1497–1540: సమ్రాట్ ప్రతాపరుద్ర దేవుని పాలన, పంచసఖ సాహిత్య వికాసం మరియు 1510లో పూరీకి శ్రీ చైతన్య మహాప్రభువు రాక.'
