        'ಕ್ರಿ.ಶ. 1464: ಕಾಂಚೀಪುರಂ ಮತ್ತು ಕಾವೇರಿ ತೀರದ ಶ್ರೀರಂಗಂವರೆಗೆ ದಕ್ಷಿಣ ದಿಗ್ವಿಜಯ.',
        'ಕ್ರಿ.ಶ. 1466–1497: ಸಮ್ರಾಟ್ ಪುರುಷೋತ್ತಮ ದೇವನ ಆಳ್ವಿಕೆ ಮತ್ತು ಕಾಂಚಿ-ಕಾವೇರಿ ಪರಂಪರೆ.',
