        '୧୪୬୪ ଖ୍ରୀ.ଅ.: କାଞ୍ଚିପୁରମ ଓ କାବେରୀ ତଟସ୍ଥ ଶ୍ରୀରଙ୍ଗମ ପର୍ଯ୍ୟନ୍ତ ଦକ୍ଷିଣ ଦିଗ୍‌ବିଜୟ।',
