      kn: 'ಶಾಸ್ತ್ರೀಯ ಮತ್ತು ಮಧ್ಯಕಾಲೀನ ಸಾಮ್ರಾಜ್ಯ ಕಾಲ (4–16ನೇ ಶತಮಾನ CE)',
      ta: 'செவ்வியல் மற்றும் இடைக்காலப் பேரரசு காலம் (4–16 ஆம் நூற்றாண்டு)',
